import{_ as s,o as t,c as n,ah as a}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Enseignement supérieur : filières, maquettes et promotions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/enseignement-superieur.md","filePath":"src/guide/admin/enseignement-superieur.md"}'),r={name:"guide/admin/enseignement-superieur.md"};function i(o,e,l,u,d,p){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="enseignement-superieur-filieres-maquettes-et-promotions" tabindex="-1">Enseignement supérieur : filières, maquettes et promotions <a class="header-anchor" href="#enseignement-superieur-filieres-maquettes-et-promotions" aria-label="Permalink to &quot;Enseignement supérieur : filières, maquettes et promotions&quot;">​</a></h1><p>Si votre établissement délivre des diplômes du supérieur (licence, master, doctorat), ERA organise ses formations selon le système LMD : des <strong>filières</strong>, enseignées à certains <strong>niveaux</strong> (L1, L2, L3…), dont la <strong>maquette</strong> répartit les crédits en <strong>unités d&#39;enseignement (UE)</strong> composées d&#39;<strong>éléments constitutifs (EC)</strong>.</p><p>L&#39;espace s&#39;ouvre par <strong>Supérieur → Filières</strong>. Il apparaît si votre licence comprend l&#39;enseignement supérieur.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><p>Les filières vivent dans un <strong>département de type « Université »</strong>, avec ses niveaux. Créez-les d&#39;abord dans le paramétrage scolaire :</p><ol><li><strong>Paramétrage → Départements</strong> : un département de type <em>Université</em>, par exemple « Faculté des sciences ».</li><li><strong>Paramétrage → Niveaux</strong> : ses niveaux, dans l&#39;ordre (L1, L2, L3, M1, M2).</li></ol><h2 id="creer-une-filiere" tabindex="-1">Créer une filière <a class="header-anchor" href="#creer-une-filiere" aria-label="Permalink to &quot;Créer une filière&quot;">​</a></h2><p>Depuis <strong>Filières</strong>, le bouton <strong>Nouvelle filière</strong> demande :</p><ul><li>le <strong>département</strong> et le <strong>nom</strong> de la filière, avec un code facultatif (« INFO ») ;</li><li>le <strong>diplôme</strong> : licence, master ou doctorat ;</li><li>le <strong>rythme</strong> : semestriel par défaut, trimestriel ou annuel ;</li><li>les <strong>crédits par an</strong>, 60 par défaut. Ils se répartissent à parts égales entre les périodes : 30 par semestre en rythme semestriel ;</li><li>les <strong>niveaux enseignés</strong> : L1 à L3 pour une licence, L3 seule pour une licence professionnelle ;</li><li>ses <strong>responsables de filière</strong>.</li></ul><p>Le rythme et le département ne changent plus une fois la maquette commencée, et une filière qui a déjà une maquette ou des promotions ne peut pas être supprimée.</p><h2 id="les-responsables-de-filiere" tabindex="-1">Les responsables de filière <a class="header-anchor" href="#les-responsables-de-filiere" aria-label="Permalink to &quot;Les responsables de filière&quot;">​</a></h2><p>Un responsable de filière tient la maquette de <strong>sa</strong> filière, et de celle-là seulement. Ce n&#39;est pas un rôle à part : un enseignant ou un membre du personnel garde son rôle habituel et reçoit en plus l&#39;espace <strong>Supérieur</strong>, limité aux filières dont il a la charge. La création et la modification des filières restent réservées à l&#39;administrateur.</p><h2 id="construire-la-maquette" tabindex="-1">Construire la maquette <a class="header-anchor" href="#construire-la-maquette" aria-label="Permalink to &quot;Construire la maquette&quot;">​</a></h2><p>Le bouton <strong>Maquette</strong> d&#39;une filière ouvre sa maquette pour une année universitaire, choisie en haut de la page. Elle est présentée niveau par niveau, puis période par période.</p><ol><li><strong>Ajouter une UE</strong> dans la période voulue : un nom, un code facultatif, et si elle est <strong>optionnelle</strong> (proposée au choix).</li><li>Dans l&#39;UE, <strong>Ajouter un EC</strong> : son nom, ses <strong>crédits</strong>, son <strong>coefficient</strong> (par défaut égal aux crédits) et son volume horaire en CM, TD et TP.</li></ol><p>Les crédits sont portés par les EC : ceux d&#39;une UE sont la somme de ses EC, ils ne peuvent donc jamais se contredire.</p><p>Une UE <strong>optionnelle</strong> est un choix, parmi quelques-unes ou librement dans l&#39;offre de la période : ses crédits <strong>complètent</strong> ceux des UE obligatoires jusqu&#39;au total de la période. Avec 24 crédits obligatoires, chaque étudiant choisit 6 crédits d&#39;options pour arriver à 30.</p><div class="tip custom-block"><p class="custom-block-title">Le compteur de crédits</p><p>Chaque période affiche ses crédits face à ce qu&#39;elle doit porter. Sans options, par exemple <strong>28 / 30 crédits</strong>. Avec des options, <strong>24 / 30 crédits obligatoires</strong>, suivi de ce qui reste à compléter et des crédits proposés : « 6 à compléter en options, sur 12 crédits proposés ». Le compteur passe au vert quand l&#39;offre permet d&#39;arriver au compte.</p></div><p>Les flèches réordonnent les UE d&#39;une période et les EC d&#39;une UE.</p><h2 id="une-maquette-par-annee" tabindex="-1">Une maquette par année <a class="header-anchor" href="#une-maquette-par-annee" aria-label="Permalink to &quot;Une maquette par année&quot;">​</a></h2><p>Chaque année universitaire a sa propre maquette. Modifier celle de cette année ne change jamais ce qu&#39;a suivi une promotion précédente.</p><p>Une nouvelle année démarre vide. ERA vous propose alors de <strong>reprendre la maquette de l&#39;année précédente</strong> en un clic : elle est copiée telle quelle, vous l&#39;ajustez ensuite. L&#39;ancienne reste intacte, et une année qui a déjà une maquette n&#39;est jamais écrasée.</p><p>Quand une année scolaire est <strong>clôturée</strong>, sa maquette l&#39;est aussi : elle reste consultable mais ne peut plus être modifiée.</p><h2 id="les-promotions" tabindex="-1">Les promotions <a class="header-anchor" href="#les-promotions" aria-label="Permalink to &quot;Les promotions&quot;">​</a></h2><p>Une <strong>promotion</strong> (par exemple « L1 Informatique 2026-2027 ») est une classe d&#39;un département universitaire. Lorsque vous créez une classe dans un tel département, ERA demande la <strong>filière</strong> qu&#39;elle suit, puis son <strong>niveau</strong>, choisi parmi ceux de la filière.</p><p>Une promotion n&#39;a ni bulletins, ni décisions de fin d&#39;année, ni réinscription en masse : ces écrans du scolaire l&#39;ignorent. Ses étudiants passent d&#39;une année à l&#39;autre d&#39;après les décisions du jury de la filière (voir <a href="#le-passage-a-l-annee-suivante">Le passage à l&#39;année suivante</a>).</p><p>Les étudiants y entrent par une <a href="/era-guide/guide/secretariat/candidatures.html#une-candidature-a-l-universite">candidature</a> qui vise la filière et le niveau.</p><h2 id="l-admission-selective" tabindex="-1">L&#39;admission sélective <a class="header-anchor" href="#l-admission-selective" aria-label="Permalink to &quot;L&#39;admission sélective&quot;">​</a></h2><p>Une filière peut recruter sur dossier : médecine, écoles d&#39;ingénieurs, masters à capacité limitée. Dans sa fiche, cochez <strong>Admission sélective</strong>, puis :</p><ul><li>fixez les <strong>places par niveau d&#39;entrée</strong>, offertes chaque année (laissez vide pour ne pas limiter un niveau) ;</li><li>désignez la <strong>commission d&#39;admission</strong>. Comme les responsables de filière, ses membres gardent leur rôle habituel et reçoivent en plus <strong>Supérieur → Admissions</strong>, limité aux filières dont ils font partie.</li></ul><p>Les candidatures à cette filière passent alors devant la commission avant toute inscription. Le formulaire prévient le candidat que son dossier sera examiné.</p><h3 id="decider-des-candidatures" tabindex="-1">Décider des candidatures <a class="header-anchor" href="#decider-des-candidatures" aria-label="Permalink to &quot;Décider des candidatures&quot;">​</a></h3><p><strong>Supérieur → Admissions</strong> liste les filières sélectives, niveau par niveau : places prises, dossiers à examiner, liste d&#39;attente, pour l&#39;année choisie en haut de la page. Le tableau de bord signale aussi aux membres de la commission les dossiers qui les attendent.</p><p>Un niveau ouvre le bureau de la commission. Les dossiers à examiner viennent d&#39;abord, dans l&#39;ordre d&#39;arrivée, puis les admis, la liste d&#39;attente dans l&#39;ordre de vos décisions, les inscrits et les refusés. Les pièces jointes s&#39;ouvrent depuis la ligne du candidat.</p><p>Le bouton <strong>Décider</strong> propose :</p><ul><li><strong>Admettre</strong> : le candidat prend une place. Quand toutes les places du niveau sont prises, ERA refuse l&#39;admission : placez-le en liste d&#39;attente ou augmentez le nombre de places ;</li><li><strong>Placer en liste d&#39;attente</strong> ;</li><li><strong>Refuser</strong>, avec un motif ;</li><li><strong>Remettre à examiner</strong>.</li></ul><p>Le candidat est prévenu par e-mail quand vous l&#39;admettez, le placez en liste d&#39;attente ou le refusez (sur son adresse, ou celle de ses tuteurs s&#39;il n&#39;en a pas donné). Le motif d&#39;un refus ne lui est pas communiqué.</p><p>Une note facultative accompagne la décision ; le secrétariat la voit, pas le candidat. Une décision reste modifiable jusqu&#39;à l&#39;inscription : si un admis se désiste, refusez-le avec le motif « désistement » et admettez le premier de la liste d&#39;attente.</p><p>Le secrétariat inscrit ensuite les admis dans une promotion de la filière, du niveau et de l&#39;année demandés.</p><h2 id="l-inscription-pedagogique" tabindex="-1">L&#39;inscription pédagogique <a class="header-anchor" href="#l-inscription-pedagogique" aria-label="Permalink to &quot;L&#39;inscription pédagogique&quot;">​</a></h2><p>Le bouton <strong>Promotions</strong> d&#39;une filière liste ses promotions pour l&#39;année choisie, avec leur effectif. Une promotion dont le niveau n&#39;a pas encore de maquette pour cette année est signalée.</p><p><strong>Inscriptions pédagogiques</strong> ouvre la page d&#39;une promotion :</p><ul><li>en haut, ses UE période par période, obligatoires et optionnelles ;</li><li>en dessous, ses étudiants, avec pour chaque période leurs crédits et les UE optionnelles qu&#39;ils ont choisies.</li></ul><p>Chaque étudiant suit <strong>toutes les UE obligatoires</strong> de son niveau : rien à saisir pour elles, et une UE ajoutée à la maquette s&#39;applique à toute la promotion. Ses <strong>UE optionnelles</strong> se choisissent avec le bouton <strong>Options</strong> de sa ligne : cochez celles qu&#39;il suit, puis enregistrez. Elles complètent les crédits de chaque période : la fenêtre indique ce qui reste à choisir, et ERA refuse un choix qui dépasse le total. Dans la liste, une période complète s&#39;affiche en vert, par exemple <strong>30 / 30 crédits</strong>.</p><p>L&#39;administrateur et les responsables de la filière tiennent ces inscriptions. Une fois l&#39;année clôturée, elles ne changent plus.</p><h2 id="les-regles-de-validation" tabindex="-1">Les règles de validation <a class="header-anchor" href="#les-regles-de-validation" aria-label="Permalink to &quot;Les règles de validation&quot;">​</a></h2><p>Chaque filière a ses propres règles, dans la section <strong>Règles de validation</strong> de sa fiche. Par défaut, celles qui ont cours dans l&#39;espace CAMES :</p><table tabindex="0"><thead><tr><th>Règle</th><th>Par défaut</th><th>Ce qu&#39;elle décide</th></tr></thead><tbody><tr><td>Part du contrôle continu</td><td>40 %</td><td>La note d&#39;un EC : contrôle continu et examen pondérés</td></tr><tr><td>Note de validation</td><td>10/20</td><td>Une UE est validée quand sa moyenne l&#39;atteint</td></tr><tr><td>Note éliminatoire</td><td>aucune</td><td>Un EC en dessous empêche son UE d&#39;être validée, même par compensation</td></tr><tr><td>Compensation entre UE</td><td>au sein du semestre</td><td>Une moyenne de période (ou d&#39;année) suffisante valide les UE en dessous</td></tr><tr><td>Plancher de compensation</td><td>aucun</td><td>Une UE sous ce plancher n&#39;est jamais compensée</td></tr><tr><td>Après le rattrapage</td><td>la meilleure note</td><td>La note de rattrapage, la meilleure des deux, ou le rattrapage plafonné</td></tr><tr><td>Crédits pour passer avec dettes</td><td>tous</td><td>En dessous, la proposition est le redoublement</td></tr></tbody></table><p>La moyenne d&#39;une UE pondère ses EC par leurs coefficients ; celle d&#39;une période ou de l&#39;année pondère les UE par leurs crédits. Une UE validée ou compensée rapporte ses crédits.</p><h2 id="enseignants-et-notes" tabindex="-1">Enseignants et notes <a class="header-anchor" href="#enseignants-et-notes" aria-label="Permalink to &quot;Enseignants et notes&quot;">​</a></h2><p>Le bouton <strong>Enseignements et notes</strong> d&#39;une promotion liste ses EC, période par période. Choisissez l&#39;enseignant de chacun, puis <strong>Enregistrer les enseignants</strong> : il retrouve ses feuilles dans <strong>Supérieur → Notes des EC</strong> (voir <a href="/era-guide/guide/enseignant/notes-superieur.html">Notes des EC</a>). Les responsables de la filière et l&#39;administrateur peuvent aussi ouvrir chaque feuille, en session normale comme en rattrapage.</p><h2 id="les-resultats" tabindex="-1">Les résultats <a class="header-anchor" href="#les-resultats" aria-label="Permalink to &quot;Les résultats&quot;">​</a></h2><p>Le bouton <strong>Résultats</strong> d&#39;une promotion donne, pour chaque étudiant, la moyenne et les crédits de chaque période et de l&#39;année, avec ce que les règles proposent : <strong>Admis</strong>, <strong>Admis avec dettes</strong> ou <strong>Redouble</strong>. Tant qu&#39;une note manque, l&#39;étudiant reste « Notes incomplètes ».</p><p>Dépliez un étudiant pour voir ses UE : moyenne, crédits et statut (validée, compensée, non validée), avec la note de chaque EC et, après un rattrapage, celle de la session normale.</p><p>Ces résultats se recalculent à chaque note saisie. La décision revient au jury de la filière. Avant la délibération de la session normale, un étudiant à qui il manque des crédits est proposé <strong>au rattrapage</strong>.</p><h2 id="les-deliberations" tabindex="-1">Les délibérations <a class="header-anchor" href="#les-deliberations" aria-label="Permalink to &quot;Les délibérations&quot;">​</a></h2><p>Le <strong>jury</strong> se compose dans la fiche de la filière. Comme les responsables, ses membres gardent leur rôle habituel et reçoivent <strong>Supérieur → Délibérations</strong>, qui liste les promotions de leurs filières et où en est chaque session : à délibérer, en cours, publiée.</p><p>Le jury délibère deux fois : après la <strong>session normale</strong>, puis après le <strong>rattrapage</strong>, qui ne s&#39;ouvre qu&#39;une fois la première délibération close.</p><p>Pour chaque étudiant, la page donne la moyenne et les crédits de l&#39;année et la décision proposée par les règles. Le bouton <strong>Décider</strong> permet :</p><ul><li>de suivre la proposition, ou de fixer une autre décision : <strong>Admis</strong>, <strong>Au rattrapage</strong> ou <strong>Exclu</strong> après la session normale ; <strong>Admis</strong>, <strong>Admis avec dettes</strong>, <strong>Redouble</strong> ou <strong>Exclu</strong> après le rattrapage ;</li><li>d&#39;ajouter des <strong>points de jury</strong> à une UE : ils s&#39;ajoutent à sa moyenne, jusqu&#39;à 20, avant qu&#39;elle soit jugée, mais ne lèvent pas une note éliminatoire ;</li><li>de laisser une note.</li></ul><p>Le rattrapage reprend les points de jury donnés après la session normale.</p><h3 id="clore-et-publier" tabindex="-1">Clore et publier <a class="header-anchor" href="#clore-et-publier" aria-label="Permalink to &quot;Clore et publier&quot;">​</a></h3><p><strong>Clore et publier</strong> publie les décisions avec les résultats sur lesquels elles reposent. Sans décision du jury, c&#39;est la proposition qui est publiée ; un étudiant dont des notes manquent doit d&#39;abord recevoir une décision. La clôture :</p><ul><li>fige les notes de la session : elles ne peuvent plus être modifiées ;</li><li>prévient chaque étudiant qui a un compte, par e-mail et dans ses notifications ;</li><li>affiche ses résultats dans son espace, sous <strong>Mes résultats</strong>.</li></ul><p>Seul l&#39;administrateur peut rouvrir une délibération (celle du rattrapage avant celle de la session normale), et plus du tout une fois des étudiants de la promotion inscrits dans l&#39;année suivante. Les étudiants gardent les résultats publiés jusqu&#39;à la clôture suivante.</p><h2 id="le-passage-a-l-annee-suivante" tabindex="-1">Le passage à l&#39;année suivante <a class="header-anchor" href="#le-passage-a-l-annee-suivante" aria-label="Permalink to &quot;Le passage à l&#39;année suivante {#le-passage-a-l-annee-suivante}&quot;">​</a></h2><p>Une fois le jury passé, le bouton <strong>Passage à l&#39;année suivante</strong> d&#39;une promotion inscrit ses étudiants dans leur promotion de l&#39;année suivante. Préparez d&#39;abord cette année : ses promotions, et sa maquette reprise de l&#39;année en cours.</p><p>Choisissez l&#39;année d&#39;arrivée. La page range les étudiants d&#39;après la <strong>décision finale</strong> du jury : celle du rattrapage, ou celle de la session normale quand elle a réglé l&#39;année (admis ou exclu).</p><ul><li><strong>Admis</strong> et <strong>admis avec dettes</strong> : dans une promotion du niveau suivant de la filière. Les dettes de chacun sont listées.</li><li><strong>Redoublent</strong> : dans une promotion du même niveau.</li><li><strong>Ont terminé la filière</strong> : les admis du dernier niveau. Ils ne sont pas réinscrits. Un étudiant admis avec dettes au dernier niveau y reste pour les solder.</li><li><strong>Exclus</strong> : ils ne sont pas réinscrits.</li><li>Les étudiants qui <strong>attendent encore</strong> le rattrapage ou le jury sont signalés, avec un lien vers les délibérations.</li></ul><p>Pour chaque groupe, choisissez la promotion d&#39;arrivée, sur le même site : quand il n&#39;y en a qu&#39;une, elle est déjà choisie. Puis cliquez sur <strong>Inscrire</strong>. Comme pour les classes du scolaire, un impayé est signalé sans bloquer, et une promotion pleine demande votre accord.</p><p>Ce que l&#39;année laisse suit l&#39;étudiant :</p><ul><li>un étudiant qui <strong>redouble garde ses UE validées ou compensées</strong>. Elles sont marquées <strong>Acquise</strong> dans ses résultats, comptent avec leur moyenne et leurs crédits, et disparaissent de ses feuilles de notes ;</li><li>un étudiant <strong>admis avec dettes</strong> emporte la liste des UE qu&#39;il doit encore valider ;</li><li>les UE optionnelles se choisissent de nouveau, sauf celles déjà acquises.</li></ul><p>ERA retrouve chaque UE dans la maquette de la nouvelle année par son code, ou à défaut par son nom. La page <strong>Inscriptions pédagogiques</strong> affiche, sous le nom de chaque étudiant, ses UE acquises et ses dettes ; une UE introuvable dans la nouvelle maquette y est signalée « hors maquette ».</p><p>Vous pouvez relancer le passage sans risque : un étudiant déjà inscrit dans l&#39;année d&#39;arrivée n&#39;est jamais déplacé. Une fois des étudiants inscrits, les délibérations de la promotion ne peuvent plus être rouvertes.</p><div class="info custom-block"><p class="custom-block-title">Ce qui reste à venir</p><p>Les dettes sont enregistrées, mais pas encore notées : leur passage aux examens du niveau inférieur viendra plus tard.</p></div>',75)])])}const g=s(r,[["render",i]]);export{m as __pageData,g as default};
